import importlib.util, json, pathlib, sys
here = pathlib.Path("tests/project_prompt").resolve()
sys.path.insert(0, str(here))
spec = importlib.util.spec_from_file_location("runner", here / "run_prompt_tests.py")
runner = importlib.util.module_from_spec(spec); sys.modules["runner"] = runner; spec.loader.exec_module(runner)
runner.CLAUDE_JUDGE = ("claude-opus-5-5", "medium")
instructions = runner.render(None)
use = [0, 0, 0]
def count(usage, judge=False):
    use[0] += 1; use[1] += usage.get("input_tokens", 0) + usage.get("cache_read_input_tokens", 0) + usage.get("cache_creation_input_tokens", 0); use[2] += usage.get("output_tokens", 0)
runner.count = count
def call(name, args): return {"type": "function_call", "call_id": "call-" + name, "name": name, "arguments": json.dumps(args)}
def reply(text): return {"type": "message", "role": "assistant", "content": [{"type": "output_text", "text": text}]}
name = "print-hook-no-purpose"
tools = runner.REQUESTS[name]["body"].get("tools", runner.TOOLS)
PLAN = next(json.loads(i["arguments"]) for i in runner.REQUESTS["print-hook-after-plan"]["body"]["input"] if i.get("name") == "setup_record")
starts = {"plan first": [[call("setup_record", PLAN)]],
          }
tally = {}
for label, script in starts.items():
    for attempt in range(5):
        scripted = iter(script)
        live, said = [], []
        def respond(input):
            step = next(scripted, None)
            if step is not None: return step
            if not live: live.append(runner.claude_cli.Run(instructions, tools, list(input), "claude-opus-5-5", "medium"))
            output, usage = live[0].next_response(); count(usage)
            said.append(output); return output
        def new_turn(input):
            if live: live.pop().close()
        deliver = lambda step, results: live and live[0].answer(step.calls, results)
        try:
            verdict, detail, _ = runner.run_steps(name, respond, deliver, new_turn)
        finally:
            if live: live[0].close()
        tally.setdefault(label, []).append(verdict)
        print("RUN", label, attempt + 1, verdict, detail[:170].replace("\n", " "), flush=True)
        for output in said:
            step = runner.Step(output)
            print("  MODEL:", (step.reply or str(step))[:900].replace("\n", " "), flush=True)
print(tally); print("usage", use)
